import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IPageITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoListUserUsers(props: {
  user: UserPayload;
  body: ITodoListUser.IRequest;
}): Promise<IPageITodoListUser.ISummary> {
  // Extract parameters
  const { email, page, limit, order_by, order_dir } = props.body;
  const currentPage = page > 0 ? page : 1;
  const perPage = limit > 0 ? limit : 100;

  // Filter
  const where =
    email !== undefined
      ? {
          email: {
            equals: email satisfies string as string,
            mode: "insensitive" as Prisma.QueryMode,
          },
        }
      : {};

  // Order
  const orderBy = [{ [order_by]: order_dir }];

  // Pagination
  const skip = (currentPage - 1) * perPage;
  const take = perPage;

  // Query
  const [users, total] = await Promise.all([
    MyGlobal.prisma.todo_list_users.findMany({
      where,
      skip,
      take,
      orderBy,
      select: { id: true },
    }),
    MyGlobal.prisma.todo_list_users.count({ where }),
  ]);

  // Compose return
  return {
    pagination: {
      current: currentPage satisfies number as number,
      limit: perPage satisfies number as number,
      records: total,
      pages: Math.ceil(total / perPage),
    },
    data: users.map((u) => ({ id: u.id })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { ITodoListSysMigration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSysMigration";

export async function postAuthUserLogin(props: {
  body: ITodoListUser.ILogin;
}): Promise<ITodoListUser.IAuthorized> {
  const user = await MyGlobal.prisma.todo_list_users.findFirst({
    where: { email: props.body.email },
  });
  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  const session_id = v4();
  const session = await MyGlobal.prisma.todo_list_user_sessions.create({
    data: {
      id: session_id,
      todo_list_user_id: user.id,
      ip: (props.body.ip ?? "") satisfies string as string,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(now),
      expired_at: toISOStringSafe(accessExpires),
    },
  });
  const access = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refresh = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token: {
      access,
      refresh,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoListUserTodos(props: {
  user: UserPayload;
  body: ITodoListTodo.ICreate;
}): Promise<ITodoListTodo> {
  const userId = props.user.id;
  const description = props.body.description;

  // Uniqueness check (case-insensitive description, exact due_date or null)
  const duplicate = await MyGlobal.prisma.todo_list_todos.findFirst({
    where: {
      user_id: userId,
      // description match, case-insensitive
      description: { equals: description, mode: "insensitive" },
      // due_date both null or both equal
      ...(props.body.due_date === null || props.body.due_date === undefined
        ? { due_date: null }
        : { due_date: props.body.due_date }),
    },
  });
  if (duplicate) {
    throw new HttpException(
      "Duplicate todo: each (description, due_date) pair must be unique per user.",
      409,
    );
  }

  // Enforce max 1000 items per user
  const totalCount = await MyGlobal.prisma.todo_list_todos.count({
    where: { user_id: userId },
  });
  if (totalCount >= 1000) {
    throw new HttpException(
      "Maximum todo limit (1000) reached for this user.",
      429,
    );
  }

  // Generate all required fields, no use of native Date
  const now = toISOStringSafe(new Date());
  const todoId = v4();

  const created = await MyGlobal.prisma.todo_list_todos.create({
    data: {
      id: todoId,
      user_id: userId,
      description: description,
      due_date: props.body.due_date === undefined ? null : props.body.due_date,
      completed: false,
      completed_at: null,
      created_at: now,
      updated_at: now,
    },
    include: {
      user: true,
    },
  });

  // Compose output, strictly following null vs undefined for optional fields
  return {
    id: created.id,
    description: created.description,
    due_date:
      created.due_date === null || created.due_date === undefined
        ? undefined
        : toISOStringSafe(created.due_date),
    completed: created.completed,
    completed_at: undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    user: {
      id: created.user.id,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { ITodoListSysMigration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSysMigration";

export async function postAuthUserRefresh(props: {
  body: ITodoListUser.IRefresh;
}): Promise<ITodoListUser.IAuthorized> {
  const { refresh_token } = props.body;
  let decoded: { id: string; session_id: string; type: "user" };
  try {
    decoded = jwt.verify(refresh_token, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    }) as { id: string; session_id: string; type: "user" };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Validate user session (not expired)
  const session = await MyGlobal.prisma.todo_list_user_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_list_user_id: decoded.id,
      expired_at: {
        gt: new Date(),
      },
    },
  });

  if (!session) {
    throw new HttpException("Session expired or not found", 401);
  }

  // Get the user record
  const user = await MyGlobal.prisma.todo_list_users.findUnique({
    where: { id: session.todo_list_user_id },
  });

  if (!user) {
    throw new HttpException("User account not found", 403);
  }

  // Generate new tokens (reuse session_id, update timestamps)
  const nowISO = toISOStringSafe(new Date());
  const accessExpISO = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpISO = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const access = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: nowISO,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refresh = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: nowISO,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  // Update the session expiration
  await MyGlobal.prisma.todo_list_user_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: new Date(refreshExpISO) },
  });

  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token: {
      access,
      refresh,
      expired_at: accessExpISO,
      refreshable_until: refreshExpISO,
    },
  };
}

