      return await patchTodoListUserTodos({
        user,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve details of a specific Todo item from the todo_list_todos table.
   *
   * Retrieve the details of a specific Todo item owned by the authenticated
   * user.
   *
   * On invocation, the API validates that the provided todoId uniquely
   * identifies an existing Todo belonging to the requester. If the Todo is
   * found and access is permitted, the response contains complete information:
   * task description, optional due date, completion boolean, and precise
   * timestamps for creation, last update, and completion (if applicable).
   *
   * Strict user isolation is enforced: the user may only access their own
   * Todos. Attempts to access a non-existent or unauthorized Todo will result
   * in a 404 Not Found or 403 Forbidden error. Sensitive ownership validation
   * is performed at every request. No information about other users' Todos is
   * ever leaked.
   *
   * Related operations: PATCH /todos (list/filter/search), POST /todos
   * (creation), PUT /todos/{todoId} (update), DELETE /todos/{todoId}
